          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\n */\n//(1)==============================================================\nimport java.util.*;\nimport java.io.*;\n\npublic class MyList {\n  Node head,tail;\n  MyList() {head=tail=null;}\n  boolean isEmpty() {\n    return(head==null);\n   }\n  void clear() {head=tail=null;}\n\n  void fvisit(Node p, RandomAccessFile f) throws Exception {\n    if(p != null) f.writeBytes(p.info + \" \");\n   }\n\n  void ftraverse(RandomAccessFile f) throws Exception {\n    Node p = head;\n    while(p!=null) {\n       fvisit(p,f); // You will use this statement to write information of the node p to the file\n       p=p.next;\n      }\n    f.writeBytes(\"\\r\\n\");\n   }\n\n  void loadData(int k) { //do not edit this function\n    String [] a = Lib.readLineToStrArray(\"data.txt\", k);\n    int [] b = Lib.readLineToIntArray(\"data.txt\", k+1);\n    int [] c = Lib.readLineToIntArray(\"data.txt\", k+2);\n    int n = a.length;\n    for(int i=0;i<n;i++) addLast(a[i],b[i],c[i]);\n   }\n\n//===========================================================================\n//(2)===YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\n//===========================================================================\n//==================================================================\n/* \n   Khong su dung tieng Viet co dau de viet ghi chu.\n   Neu dung khi chay truc tiep se bao loi va nhan 0 diem\n*/\n  void addLast(String xMaker, int xVolume, int xColor) {\n    //You should write here appropriate statements to complete this function.\n    if (xMaker != null && xMaker.charAt(0) == 'B') {\n      return;\n    }\n    Node node = new Node(new Bottle(xMaker, xVolume, xColor));\n    if (isEmpty()) {\n      head = tail = node;\n    } else {\n      tail.next = node;\n      tail = node;\n    }\n   }\n\n  //You do not need to edit this function. Your task is to complete the addLast function above only.\n  void f1() throws Exception {\n     clear();\n     loadData(1);\n     String fname = \"f1.txt\";\n     File g123 = new File(fname);\n     if(g123.exists()) g123.delete();\n     RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n     ftraverse(f);\n     f.close();\n    }  \n\n//==================================================================\n  void f2() throws Exception {\n     clear();\n     loadData(5);\n     String fname = \"f2.txt\";\n     File g123 = new File(fname);\n     if(g123.exists()) g123.delete();\n     RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n     ftraverse(f);\n     Bottle x, y, z;\n     x = new Bottle(\"X\",1,2);\n     y = new Bottle(\"Y\",2,3);\n     z = new Bottle(\"Z\",3,4);\n     //------------------------------------------------------------------------------------\n     /*You must keep statements pre-given in this function.\n       Your task is to insert statements here, just after this comment,\n       to complete the question in the exam paper.*/\n\n     insertAt(x, 0);\n     insertAt(y, 2);\n     insertAt(z, 3);\n\n    //------------------------------------------------------------------------------------\n     ftraverse(f);\n     f.close();\n    }\n\n  // insert node with data at 0-indexed position pos (head's position is 0)\n  void insertAt(Bottle data, int pos) {\n    Node node = new Node(data);\n    if (pos == 0 || head == null) {\n      node.next = head;\n      head = node;\n      if (tail == null) tail = node;\n      return;\n    }\n    Node prev = head;\n    for (int i = 0; i < pos - 1 && prev.next != null; i++) prev = prev.next;\n    node.next = prev.next;\n    prev.next = node;\n    if (node.next == null) tail = node;\n  }\n\n//==================================================================\n  void f3() throws Exception {\n    clear();\n    loadData(9);\n    String fname = \"f3.txt\";\n    File g123 = new File(fname);\n    if(g123.exists()) g123.delete();\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n    ftraverse(f);\n    //------------------------------------------------------------------------------------\n     /*You must keep statements pre-given in this function.\n       Your task is to insert statements here, just after this comment,\n       to complete the question in the exam paper.*/\n\n    // find the first node with maximum volume, remove it, then insert at position 2\n    Node p = head, maxNode = head;\n    while (p != null) {\n      if (p.info.volume > maxNode.info.volume) maxNode = p;\n      p = p.next;\n    }\n    // unlink maxNode\n    if (maxNode == head) {\n      head = head.next;\n      if (head == null) tail = null;\n    } else {\n      Node prev = head;\n      while (prev.next != maxNode) prev = prev.next;\n      prev.next = maxNode.next;\n      if (maxNode == tail) tail = prev;\n    }\n    insertNodeAt(maxNode, 2);\n\n    //------------------------------------------------------------------------------------\n    ftraverse(f);\n    f.close();\n  }\n\n  // insert an existing (already-unlinked) node at 0-indexed position pos\n  void insertNodeAt(Node node, int pos) {\n    node.next = null;\n    if (pos == 0 || head == null) {\n      node.next = head;\n      head = node;\n      if (tail == null) tail = node;\n      return;\n    }\n    Node prev = head;\n    for (int i = 0; i < pos - 1 && prev.next != null; i++) prev = prev.next;\n    node.next = prev.next;\n    prev.next = node;\n    if (node.next == null) tail = node;\n  }\n\n//==================================================================\n  void f4() throws Exception {\n    clear();\n    loadData(13);\n    String fname = \"f4.txt\";\n    File g123 = new File(fname);\n    if(g123.exists()) g123.delete();\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n    ftraverse(f);\n    //------------------------------------------------------------------------------------\n     /*You must keep statements pre-given in this function.\n       Your task is to insert statements here, just after this comment,\n       to complete the question in the exam paper.*/\n\n    // p = 6th element (1-indexed); change its volume to 99, then sort the nodes before p ascending by volume\n    Node p = head;\n    for (int i = 1; i < 6 && p != null; i++) p = p.next;\n    p.info.volume = 99;\n    // collect nodes strictly before p\n    java.util.List<Node> before = new java.util.ArrayList<>();\n    Node q = head;\n    while (q != p) { before.add(q); q = q.next; }\n    // selection sort ascending by volume, swap info only\n    for (int i = 0; i < before.size(); i++) {\n      int minIdx = i;\n      for (int j = i + 1; j < before.size(); j++) {\n        if (before.get(j).info.volume < before.get(minIdx).info.volume) minIdx = j;\n      }\n      if (minIdx != i) {\n        Bottle tmp = before.get(i).info;\n        before.get(i).info = before.get(minIdx).info;\n        before.get(minIdx).info = tmp;\n      }\n    }\n\n    //------------------------------------------------------------------------------------\n    ftraverse(f);\n    f.close();\n   }\n\n }\n\n",
