          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\n */\n//(1)============================================\nimport java.io.*;\nimport java.util.*;\n//-------------------------------------------------------------------------------\npublic class Graph {\n  int [][] a; int n;\n  char v[];\n  int deg[];\n  Graph() {\n    v = \"ABCDEFGHIJKLMNOP\".toCharArray();\n    deg = new int[20];\n    a = new int[20][20];\n    n = 0;\n   }\n\n  void loadData(int k) {  //do not edit this function\n    RandomAccessFile f;int i,j,x;\n    String s;StringTokenizer t;\n    a = new int[20][20];\n    try {\n     f = new RandomAccessFile(\"data.txt\",\"r\");\n     for(i=0;i<k;i++) f.readLine();\n     s = f.readLine();s = s.trim();\n     n = Integer.parseInt(s);\n     for(i=0;i<n;i++) {\n       s = f.readLine();s = s.trim();\n       t = new StringTokenizer(s);\n       for(j=0;j<n;j++) { \n         x = Integer.parseInt(t.nextToken().trim());\n         a[i][j] = x;\n        }\n       }\n     f.close();\n     }\n    catch(Exception e) {}\n\n   }\n\n  void dispAdj() {\n    int i,j;\n    for(i=0;i<n;i++) {\n      System.out.println();\n      for(j=0;j<n;j++)\n        System.out.printf(\"%4d\",a[i][j]);\n     }\n   }\n\n  void fvisit(int i, RandomAccessFile f) throws Exception {\n    f.writeBytes(\"  \"+v[i]);\n   }\n\n void fdispAdj(RandomAccessFile f) throws Exception { \n    int i,j;\n    f.writeBytes(\"n = \"+n+\"\\r\\n\");\n    for(i=0;i<n;i++) {\n      f.writeBytes(\"\\r\\n\");\n      for(j=0;j<n;j++)  f.writeBytes(\"  \" + a[i][j]);\n     }\n    f.writeBytes(\"\\r\\n\");\n   }\n\n  void breadth(boolean [] en, int i, RandomAccessFile f) throws Exception {\n    Queue q = new Queue();\n    int r,j;\n    q.enqueue(i); en[i]=true;\n    while(!q.isEmpty()) {\n      r = q.dequeue();\n      fvisit(r,f);\n      for(j=0;j<n;j++) {\n        if(!en[j] && a[r][j]>0) {\n         q.enqueue(j);en[j]=true;\n        }\n       }\n     }\n   }\n\n  void breadth(int  k, RandomAccessFile f) throws Exception {\n    boolean [] en = new boolean[20];\n    int i;\n    for(i=0;i<n;i++) en[i]=false;\n    breadth(en,k,f);\n    for(i=0;i<n;i++) \n      if(!en[i]) breadth(en,i,f);\n   }\n\n void depth(boolean [] visited,int k, RandomAccessFile f) throws Exception {\n    fvisit(k,f);visited[k]=true;\n    for(int i=0;i<n;i++) {\n      if(!visited[i] && a[k][i]>0) depth(visited,i,f);\n     }\n   }\n  void depth(int k, RandomAccessFile f) throws Exception {\n    boolean [] visited = new boolean[20];\n    int i;\n    for(i=0;i<n;i++) visited[i]=false;\n    depth(visited,k,f);\n    for(i=0;i<n;i++) \n       if(!visited[i]) depth(visited,i,f);\n   }\n\n//===========================================================================\n//(2)===YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\n//===========================================================================\n  void f1() throws Exception {\n    loadData(1);\n    String fname = \"f1.txt\";\n    File g123 = new File(fname);\n    if(g123.exists()) g123.delete();\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n    breadth(3,f);\n    f.writeBytes(\"\\r\\n\");\n    //-------------------------------------------------------------------------------------\n     /*You must keep statements pre-given in this function.\n       Your task is to insert statements here, just after this comment,\n       to complete the question in the exam paper.*/\n\n    posCounter = 0;\n    boolean[] en2 = new boolean[20];\n    breadth2(en2, 3, f);\n    for (int i = 0; i < n; i++) if (!en2[i]) breadth2(en2, i, f);\n\n    //-------------------------------------------------------------------------------------\n    f.writeBytes(\"\\r\\n\");\n    f.close();\n   }\n\n  int posCounter;\n  void breadth2(boolean[] en, int i, RandomAccessFile f) throws Exception {\n    Queue q = new Queue();\n    int r, j;\n    q.enqueue(i); en[i] = true;\n    while (!q.isEmpty()) {\n      r = q.dequeue();\n      posCounter++;\n      if (posCounter >= 4 && posCounter <= 8) fvisit(r, f);\n      for (j = 0; j < n; j++) {\n        if (!en[j] && a[r][j] > 0) {\n          q.enqueue(j); en[j] = true;\n        }\n      }\n    }\n  }\n\n//=================================================================================================\n void f2() throws Exception {\n    loadData(12);\n    String fname = \"f2.txt\";\n    File g123 = new File(fname);\n    if(g123.exists()) g123.delete();\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n    //-------------------------------------------------------------------------------------\n     /*You must keep statements pre-given in this function.\n       Your task is to insert statements here, just after this comment,\n       to complete the question in the exam paper.*/\n      // You can use the statement fvisit(i,f); i = 0, 1, 2,...,n-1 to display the vertex i to file f2.txt \n      //  and statement f.writeBytes(\" \" + k); to write  variable k to the file f2.txt  \n\n    // Part 1: Dijkstra from vertex 1 (B) to vertex 5 (F) -- report the actual path\n    int[] path1 = dijkstraPath(1, 5);\n    for (int v : path1) fvisit(v, f);\n    f.writeBytes(\"\\r\\n\");\n\n    // Part 2: Dijkstra from vertex 0 (A) to vertex 6 (G)\n    int[] dist = new int[n];\n    int[] pred = new int[n];\n    boolean[] inS = new boolean[n];\n    int[] order = new int[n];\n    for (int i = 0; i < n; i++) { dist[i] = a[0][i]; pred[i] = 0; }\n    inS[0] = true; order[0] = 0; dist[0] = 0;\n    int selCount = 1;\n    while (selCount < n) {\n      int u = -1, best = Integer.MAX_VALUE;\n      for (int i = 0; i < n; i++) {\n        if (!inS[i] && dist[i] < best) { best = dist[i]; u = i; }\n      }\n      inS[u] = true;\n      order[selCount] = u;\n      selCount++;\n      for (int j = 0; j < n; j++) {\n        if (!inS[j] && dist[u] + a[u][j] < dist[j]) {\n          dist[j] = dist[u] + a[u][j];\n          pred[j] = u;\n        }\n      }\n    }\n    for (int t = n - 3; t < n; t++) fvisit(order[t], f);\n    f.writeBytes(\"\\r\\n\");\n    java.util.List<Integer> path2 = new java.util.ArrayList<>();\n    int cur = 6;\n    while (true) { path2.add(0, cur); if (cur == 0) break; cur = pred[cur]; }\n    for (int v : path2) { fvisit(v, f); f.writeBytes(\"|\" + dist[v]); }\n\n    //-------------------------------------------------------------------------------------\n    f.writeBytes(\"\\r\\n\");\n    f.close();\n   }\n\n  // Dijkstra from src to dst, returning the actual shortest path as an array of vertex indices\n  int[] dijkstraPath(int src, int dst) {\n    int[] dist = new int[n];\n    int[] pred = new int[n];\n    boolean[] inS = new boolean[n];\n    for (int i = 0; i < n; i++) { dist[i] = a[src][i]; pred[i] = src; }\n    inS[src] = true; dist[src] = 0;\n    int selCount = 1;\n    while (selCount < n) {\n      int u = -1, best = Integer.MAX_VALUE;\n      for (int i = 0; i < n; i++) {\n        if (!inS[i] && dist[i] < best) { best = dist[i]; u = i; }\n      }\n      if (u == -1) break;\n      inS[u] = true;\n      selCount++;\n      for (int j = 0; j < n; j++) {\n        if (!inS[j] && dist[u] + a[u][j] < dist[j]) {\n          dist[j] = dist[u] + a[u][j];\n          pred[j] = u;\n        }\n      }\n    }\n    java.util.List<Integer> path = new java.util.ArrayList<>();\n    int cur = dst;\n    while (true) { path.add(0, cur); if (cur == src) break; cur = pred[cur]; }\n    int[] result = new int[path.size()];\n    for (int i = 0; i < path.size(); i++) result[i] = path.get(i);\n    return result;\n  }\n\n}\n",
